export function formatDrugDisplayName(entry: DrugDictionaryEntry): string {
  const brandPart = entry.brandLabel && entry.brandLabel !== "—" ? ` (${entry.brandLabel})` : "";
  return `${entry.genericName}${brandPart} ${entry.strength} - ${entry.formulation}`;
}
